pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }
    function testFuzz_property(address from, address callee, uint256 v0, uint256 v1, uint256 v2, uint256 len) public {
        uint256 l = bound(len, 1, 3);

        address[] memory tos = new address[](l);
        uint[] memory vals = new uint[](l);
        if (l > 0) { tos[0] = callee; vals[0] = v0; }
        if (l > 1) { tos[1] = address(uint160(uint256(keccak256(abi.encodePacked(callee, v1))))); vals[1] = v1; }
        if (l > 2) { tos[2] = address(uint160(uint256(keccak256(abi.encodePacked(callee, v2))))); vals[2] = v2; }

        bool ok;
        try c.transfer(from, callee, tos, vals) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
